def tree_from(levels):
    # [1, 2, 3, None, None, 4, 5]: level by level, left to right, None for a missing child (a missing node has no children listed)
    nodes = [None if v is None else TreeNode(v) for v in levels]
    children = iter(nodes[1:])
    for node in nodes:
        if node is not None:
            node.left = next(children, None)
            node.right = next(children, None)
    return nodes[0] if nodes else None
def levels_of(root):
    # the inverse of tree_from: the tree as its levels, with None for a missing child and no trailing Nones
    out, queue = [], [root]
    for node in queue:
        if node is None:
            out.append(None)
        else:
            out.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
    while out and out[-1] is None:
        out.pop()
    return out
def wreck(root):
    # change the original tree beyond recognition: the text alone must be enough to rebuild it
    stack = [root]
    while stack:
        node = stack.pop()
        if node is not None:
            stack.append(node.left)
            stack.append(node.right)
            node.val, node.left, node.right = -999, None, None
def round_trips(levels):
    original = tree_from(levels)
    expected = levels_of(original)
    text = serialize(original)
    if not isinstance(text, str):
        raise AssertionError(f"serialize must return a str, not {type(text).__name__}")
    wreck(original)
    for attempt in (1, 2):
        rebuilt = deserialize(text)
        if rebuilt is not None and not isinstance(rebuilt, TreeNode):
