from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


MISSING = "#"


def serialize(root):
    """Level by level, with a marker for every missing child: 1,2,3,#,#,4,5,#,#,#,#"""
    tokens = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node is None:
            tokens.append(MISSING)
        else:
            tokens.append(str(node.val))
            queue.append(node.left)
            queue.append(node.right)
    return ",".join(tokens)


def deserialize(text):
    tokens = text.split(",")
    if tokens[0] == MISSING:
        return None
    root = TreeNode(int(tokens[0]))
    queue = deque([root])
    position = 1
    while queue:
        node = queue.popleft()               # the next two tokens are this node's children
        if tokens[position] != MISSING:
            node.left = TreeNode(int(tokens[position]))
            queue.append(node.left)
        if tokens[position + 1] != MISSING:
            node.right = TreeNode(int(tokens[position + 1]))
            queue.append(node.right)
        position += 2
    return root
